<?php

namespace AppBundle\Repository;

use AppBundle\Entity\opportunite;
use \Datetime;
use AppBundle\Entity\candidat;
use AppBundle\Entity\utilisateur;
use AppBundle\Entity\technologie;
/**
 * opportuniteRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class opportuniteRepository extends \Doctrine\ORM\EntityRepository
{
    protected function persistAndFlush($entity)
    {
        $this->getEntityManager()->persist($entity);
        $this->getEntityManager()->flush();
        
    }
    
    protected function removeAndFlush($entity)
    {
        $this->getEntityManager()->remove($entity);
        $this->getEntityManager()->flush();
        
    }
    
    public function findAll()
    {
        return $this->findBy(array('etat' => 'Active'), array('dateDemarrageSouhaitee' => 'ASC'));
    }
    
