    {
        
        $opportunites = $this->findAll();

        $listeFinaleOpportunites = array();
        
        foreach ($opportunites as $opportunite)
        {
            $dateAjout = "N/A";
            $dateDemarrageSouhaitee = "N/A";
            $tjm = "N/A";
            $photo = "bootstrap/img/profile.jpg";
            
            
            if(!empty($opportunite->getDateAjout()))
            {
                $dateAjout = $opportunite->getDateAjout()->format('d-m-Y');
            }
            
            if(!empty($opportunite->getDateDemarrageSouhaitee()))
            {
                $dateDemarrageSouhaitee = $opportunite->getDateDemarrageSouhaitee()->format('d-m-Y');
            }
            
            if(!empty($opportunite->getTjm()))
            {
                $tjm = $opportunite->getTjm();
            }
            
            if(!empty($opportunite->getUtilisateur()->getPhoto()))
            {
                $photo = $opportunite->getUtilisateur()->getPhoto();
            }
            
            
            $listeOpportunites = Array(
                'id' => $opportunite->getId(),
                'titre' => $opportunite->getTitre(),
                'etat' => $opportunite->getEtat(),
                'descriptionDetaillee' => $opportunite->getDescriptionDetaillee(),
                'dateAjout' => $dateAjout,
                'tjm' => $tjm,
                'dateDemarrageSouhaitee' => $dateDemarrageSouhaitee,
                
                
                'utilisateur' => $opportunite->getUtilisateur()->getPrenom().' '.$opportunite->getUtilisateur()->getNom(),
                'idUtilisateur' => $opportunite->getUtilisateur()->getId(),
                'photo' => $photo,
                
                'listeCandidats' => $opportunite->getListeCandidats(),
                'listeTechnologies' => $opportunite->getListeTechnologies()
                
                );
            
            $listeFinaleOpportunites[] = $listeOpportunites;
        }
        return $listeFinaleOpportunites;
        
    }
    
