        return $listeOpportunites;
        
    }
    
    public function deleteOpportunite($idOpportunite)
    {
        $opportunite = $this->findOneBy(array('id' => $idOpportunite));
        
        $this->removeAndFlush($opportunite);
    }
    
    public function addOpportunite($request)
    {
        $opportunite = new opportunite();
        
        $opportunite->setEtat("Active");
        
        if(!empty($request->get('titre')))
        {
            $opportunite->setTitre($request->get('titre'));
        }
        
        if(!empty($request->get('descriptionDetaillee')))
        {
            $opportunite->setDescriptionDetaillee($request->get('descriptionDetaillee'));
        }

        if(!empty($request->get('dateDemarrageSouhaitee')))
        {
            $opportunite->setDateDemarrageSouhaitee(new DateTime($request->get('dateDemarrageSouhaitee')));
        }
        
        $opportunite->setDateAjout(new DateTime());
        
        if(!empty($request->get('tjm')))
        {
            $opportunite->setTjm($request->get('tjm'));
        }
        
        //Ajout du Partenaire responsable de l'opportunité
        if(!empty($request->get('listePartenaires')))
        {
            $partenaireRepository = $this->getEntityManager()->getRepository(utilisateur::class);
            $partenaire = $partenaireRepository->findOneBy(array('id' => $request->get('listePartenaires')));
            $opportunite->setUtilisateur($partenaire);
        }
        
        
        //Ajout des candidats potentiels à l'opportunité
        if(!empty($_POST['listeCandidats']))
        {
            //Parcours et Ajout des candidats
            foreach ($_POST['listeCandidats'] as $idCandidat)
            {
                $candidatRepository = $this->getEntityManager()->getRepository(candidat::class);
                $candidat = $candidatRepository->findOneBy(array('id' => $idCandidat));
                
                $opportunite->addCandidat($candidat);
            }
        }
        
        //Ajout des technologies (une ou plusieurs)
        if(!empty($_POST['listeTechnologies']))
        {
            //Parcours et Ajout des technologies
            foreach ($_POST['listeTechnologies'] as $Technologie)
            {
                $technologieRepository = $this->getEntityManager()->getRepository(technologie::class);
                $technologie = $technologieRepository->findOneBy(array('id' => $Technologie));
                
                if(empty($technologie))
                {
                    $technologie = new technologie();
                    $technologie->setNom($technologie);
                    $this->persistAndFlush($technologie);
                }
                $opportunite->addTechnologie($technologie);
            }
            $this->persistAndFlush($opportunite);
        }
        
        $this->persistAndFlush($opportunite);
    }
    
    public function updateOpportunite($request)
    {
        
        $opportunite = $this->findOneBy(array('id' => $request->get('id')));
        
        if(!empty($request->get('titre')))
        {
            $opportunite->setTitre($request->get('titre'));
        }
        
        if(!empty($request->get('descriptionDetaillee')))
        {
            $opportunite->setDescriptionDetaillee($request->get('descriptionDetaillee'));
        }
        
        if(!empty($request->get('dateDemarrageSouhaitee')))
        {
            $opportunite->setDateDemarrageSouhaitee(new DateTime($request->get('dateDemarrageSouhaitee')));
        }
        
        //$opportunite->setDateAjout(new DateTime());
        
        if(!empty($request->get('tjm')))
        {
            $opportunite->setTjm($request->get('tjm'));
        }
        
        //Ajout du Partenaire responsable de l'opportunité
        if(!empty($request->get('listePartenaires')))
        {
            $partenaireRepository = $this->getEntityManager()->getRepository(utilisateur::class);
            $partenaire = $partenaireRepository->findOneBy(array('id' => $request->get('listePartenaires')));
            $opportunite->setUtilisateur($partenaire);
        }
        
        
        //Ajout des candidats potentiels à l'opportunité
        if(!empty($_POST['listeCandidats']))
        {
            //Parcours et Ajout des candidats
            foreach ($_POST['listeCandidats'] as $idCandidat)
            {
                $candidatRepository = $this->getEntityManager()->getRepository(candidat::class);
                $candidat = $candidatRepository->findOneBy(array('id' => $idCandidat));
                
                if (!$opportunite->getListeCandidats()->contains($candidat))
                {
                    $opportunite->addCandidat($candidat);
                }  
            }
            
        }
        
        //Ajout des technologies (une ou plusieurs)
        if(!empty($_POST['listeTechnologies']))
        {
            //Parcours et Ajout des technologies
            foreach ($_POST['listeTechnologies'] as $Technologie)
            {
                $technologieRepository = $this->getEntityManager()->getRepository(technologie::class);
                $technologie = $technologieRepository->findOneBy(array('id' => $Technologie));
                
                if (!$opportunite->getListeTechnologies()->contains($technologie))
                {
                    $opportunite->addTechnologie($technologie);
                }
                
            }
            $this->persistAndFlush($opportunite);
        }
        
        $this->persistAndFlush($opportunite);
    }
    
    public function removeCandidatForOpportunite($idOpportunite, $idCandidat)
    {
        
        $opportunite = $this->findOneBy(array('id' => $idOpportunite));
        
        $candidatRepository = $this->getEntityManager()->getRepository(candidat::class);
        $candidat = $candidatRepository->findOneBy(array('id' => $idCandidat));
        
        $opportunite->removeCandidat($candidat);
        
        $this->persistAndFlush($opportunite);
        
    }
    
    public function removeTechnologieForOpportunite($idOpportunite,$idTechnologie)
    {
        $opportunite = $this->findOneBy(array('id' => $idOpportunite));
        
        $technologieRepository = $this->getEntityManager()->getRepository(technologie::class);
        $technologie = $technologieRepository->findOneBy(array('id' => $idTechnologie));
        
        $opportunite->removeTechnologie($technologie);
        
        $this->persistAndFlush($opportunite);
        
    }
    
    public function archiveOpportunite($idOpportunite)
    {
        $opportunite = $this->findOneBy(array('id' => $idOpportunite));
        
        $opportunite->setEtat("Archive");
        
        $this->persistAndFlush($opportunite);
    }
    
    public function activeOpportunite($idOpportunite)
    {
        $opportunite = $this->findOneBy(array('id' => $idOpportunite));
        
        $opportunite->setEtat("Active");
        
        $this->persistAndFlush($opportunite);
    }
    
